async function bindAccountHeader(){
  const updateCount=event=>{
    const count=Object.values(localLibrary().cart).reduce((sum,value)=>sum+Number(value||0),0);
    document.querySelectorAll('[data-cart-count]').forEach(badge=>{badge.textContent=count;badge.hidden=!count});
    if(event?.detail?.type==='ratings')bindRatingSummaries().catch(()=>null);
  };
  updateCount();
  window.addEventListener('shoplab:library-change',updateCount);
  const menus=[...document.querySelectorAll('.account-menu')];
  menus.forEach(menu=>{
    const summary=menu.querySelector(':scope>summary');
    const dropdown=menu.querySelector(':scope>.account-dropdown');
    if(!summary||!dropdown)return;
    const positionMenu=()=>{
      if(!menu.open)return;
      const rect=summary.getBoundingClientRect();
      const top=Math.round(rect.bottom+8);
      const right=Math.max(10,Math.round(innerWidth-rect.right));
      menu.style.setProperty('--account-menu-top',`${top}px`);
      menu.style.setProperty('--account-menu-right',`${right}px`);
      dropdown.style.setProperty('--account-menu-top',`${top}px`);
      dropdown.style.setProperty('--account-menu-right',`${right}px`);
    };
    summary.addEventListener('click',event=>{
      event.preventDefault();
      const shouldOpen=!menu.open;
      menus.forEach(other=>{if(other!==menu)other.removeAttribute('open')});
      menu.open=shouldOpen;
    });
    menu.addEventListener('toggle',()=>{
      if(menu.open){
        if(matchMedia('(max-width:760px)').matches&&dropdown.parentNode!==document.body)document.body.append(dropdown);
        requestAnimationFrame(positionMenu);
      }else if(dropdown.parentNode!==menu)menu.append(dropdown);
    });
    addEventListener('resize',positionMenu,{passive:true});
    addEventListener('scroll',positionMenu,{passive:true});
  });
  const user=await currentUser();
  if(!user)return;
  const name=String(user.user_metadata?.display_name||user.user_metadata?.full_name||user.email?.split('@')[0]||'Minha conta');
  const avatar=String(user.user_metadata?.avatar_url||user.user_metadata?.picture||'');
  rememberAccountHeader({name,avatar});
  document.querySelectorAll('[data-account-name]').forEach(item=>item.textContent=name);
  document.querySelectorAll('[data-account-email]').forEach(item=>item.textContent=user.email||'');
  document.querySelectorAll('[data-account-avatar]').forEach(item=>{
    item.innerHTML=avatar?`<img src="${esc(avatar)}" alt="Foto de ${esc(name)}" referrerpolicy="no-referrer">`:`<b>${esc(name.trim().split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase())}</b>`;
  });
  document.querySelectorAll('[data-account-signout]').forEach(button=>button.addEventListener('click',async()=>{
    await signOut();
    location.replace('index.html');
  }));
  document.addEventListener('click',event=>menus.forEach(menu=>{
    const dropdown=menu.querySelector(':scope>.account-dropdown');
    if(menu.open&&!menu.contains(event.target)&&!dropdown?.contains(event.target))menu.removeAttribute('open');
  }));
}function paintRatingSummary(target,average,total){const count=Number(total)||0,numericAverage=Math.max(0,Math.min(5,Number(average)||0)),score=Math.round(numericAverage),starHtml=Array.from({length:5},(_,i)=>i<score?`<i class="rating-star" style="--star-i:${i}">★</i>`:`<i class="rating-star empty">☆</i>`).join(''),averageLabel=numericAverage.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1}),countLabel=Number(count).toLocaleString('pt-BR');target.hidden=false;target.dataset.ratingAverage=String(numericAverage);target.dataset.ratingTotal=String(count);target.classList.toggle('is-empty',count===0);target.classList.toggle('has-glowing-stars',count>0&&numericAverage>=4.5);target.innerHTML=count?`<span class="rating-stars" style="--star-count:${score};--star-glow-delay:${(Math.random()*2.6).toFixed(2)}s;--star-step:${(0.55+Math.random()*0.45).toFixed(2)}s" aria-label="${averageLabel} de 5 estrelas">${starHtml}</span><strong class="rating-average">${averageLabel}</strong><small>· ${countLabel} ${count===1?'pessoa':'pessoas'}</small>`:'<span class="rating-stars" aria-hidden="true">☆☆☆☆☆</span><small>Ainda sem avaliações</small>'}
function updateRatingOptimistically({slug,rating,oldValue}){document.querySelectorAll(`[data-rating-summary="${CSS.escape(slug)}"]`).forEach(target=>{const total=Number(target.dataset.ratingTotal)||0,average=Number(target.dataset.ratingAverage)||0,previous=Number(oldValue)||0,next=Number(rating)||0,newTotal=previous?total:total+1,newAverage=newTotal?((average*total)-previous+next)/newTotal:next;paintRatingSummary(target,newAverage,newTotal)})}
